<script setup>import { computed } from 'vue'; import { mockAnalysis } from '../data/mockAnalysis'; const props = defineProps({ selectedText: String, result: Object }); const analysis = computed(() => props.result || mockAnalysis.grammar)</script><template><section class="analysis"><h3>语法分析</h3><label>原句</label><blockquote>{{ selectedText || mockAnalysis.grammar.original }}</blockquote><h4>{{ analysis.sentence_pattern || analysis.result }}</h4><p>还原：{{ analysis.modern_order || analysis.restored }}</p><ul><li v-for="part in (analysis.components || analysis.parts)">{{ part.text ? `${part.text}：${part.role}` : part }}</li></ul><small>{{ analysis.explanation || analysis.note }}</small></section></template>
